+        stageLoader = new StageLoader(table);
+        Toolkit.getToolkit().firePulse();
+
+        table.setPrefHeight(100);
+        Toolkit.getToolkit().firePulse();
+
+        int index = 8;
+        Person person = table.getItems().get(index);
